head.script:
        	scwin.onpageload = function() {

        	}


	scwin.simulateWrapper = function(target, type, options) {
		WebSquare.wUnit.getJq(target).simulate(type, options);
	}
	scwin.setSimulate1 = function() {
		scwin.simulateWrapper('#acb_samp_input', 'key-combo', {
			combo: 'ENTER'
		});
	}
	scwin.setSimulate1 = function() {
		scwin.simulateWrapper('#input1', 'key-sequence', {
			sequence: '1.56789'
		});
	}
	scwin.setSimulate2 = function() {
		scwin.simulateWrapper('#input2', 'key-sequence', {
			sequence: '1.56789'
		});
	}
	scwin.setSimulate3 = function() {
		scwin.simulateWrapper('#input1', 'key-sequence', {
			sequence: ''
		});
	}

	scwin.checkVal = function() {
		return WebSquare.wUnit.getDomById('input1').value == '1.56789';
	}	

	scwin.unitTest = function(){
		//init
		WebSquare.wUnit.start();

		WebSquare.wUnit.addCommand("pause", "500");		

		WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getDomById('input1').click()");
		WebSquare.wUnit.addCommand("pause", "500");			

		WebSquare.wUnit.addCommand("set", "scwin.setSimulate1()");
		WebSquare.wUnit.addCommand("pause", "500");

		WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getDomById('input2').click()");
		WebSquare.wUnit.addCommand("pause", "500");		

		WebSquare.wUnit.addCommand("set", "scwin.setSimulate2()");
		WebSquare.wUnit.addCommand("pause", "500");

		WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getDomById('input1').click()");
		WebSquare.wUnit.addCommand("pause", "500");				

		WebSquare.wUnit.addCommand("set", "scwin.setSimulate3()");
		WebSquare.wUnit.addCommand("pause", "500");

		WebSquare.wUnit.addCommand("assert", "scwin.checkVal()", "true");
		WebSquare.wUnit.addCommand("pause", "500");		

		//Run  and stop
		WebSquare.wUnit.run();
		WebSquare.wUnit.stop();
	}
	scwin.unitTest();
